1036	    // triângulo apontando pra baixo
1037	    doc.triangle(x, triTop, x + 2, triTop, x + 1, triBot, 'F');
1038	  } else {
1039	    // triângulo apontando pra cima
1040	    doc.triangle(x + 1, triTop, x, triBot, x + 2, triBot, 'F');
