const currentTotal = agg.totalValue;
const prev = params.comparativo;
if (prev) {
  if (prev.prevTotal > 0) {
    const delta = ((currentTotal - prev.prevTotal) / prev.prevTotal) * 100;
    const reduziu = delta < 0;
    const tint: [number, number, number] = reduziu ? [236, 248, 240] : [252, 237, 237];
    const borderColor: [number, number, number] = reduziu ? [34, 197, 94] : [239, 68, 68];
    const textoEscuro: [number, number, number] = reduziu ? [22, 120, 60] : [150, 40, 40];

    doc.setFillColor(...tint);
    doc.setDrawColor(...borderColor);
    doc.setLineWidth(0.3);
    doc.roundedRect(15, cursorY, pageWidth - 30, 10, 2, 2, 'FD');

    drawDeltaIndicator(doc, 20, cursorY + 6.5, delta);

    const texto = reduziu
      ? `Perdas menores que no mesmo período do mês anterior (${prev.prevPeriodoLabel})`
      : `Perdas maiores que no mesmo período do mês anterior (${prev.prevPeriodoLabel})`;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8.5);
    doc.setTextColor(...textoEscuro);
    doc.text(texto, 40, cursorY + 6.3);

    cursorY += 10 + 6;
